# ---------------------------------------------------------------- errors ---
class MimicError(RuntimeError):
    """Base class of every error a generated client raises."""


class TransportError(MimicError):
    """The request never produced an HTTP response (DNS, TCP, TLS, reset...)."""


class RequestTimeout(TransportError):
    """An attempt exceeded ``timeout`` or the whole call exceeded ``deadline``."""


class HTTPError(MimicError):
    """The server answered with a 4xx/5xx status."""

    def __init__(
        self, status: int, url: str, body: bytes = b"", headers: Mapping[str, str] | None = None
    ) -> None:
        self.status, self.url, self.body = status, url, body
        self.headers: Headers = dict(headers or {})
        super().__init__(f"HTTP {status} for {url.split('?')[0]}: {body[:300]!r}")


class ClientHTTPError(HTTPError):
    """4xx (the request is wrong or unauthorized)."""


class RateLimited(ClientHTTPError):
    """429 Too Many Requests after all retries."""


class ServerHTTPError(HTTPError):
    """5xx (the server failed)."""


class RobotsDisallowed(MimicError):
    """robots.txt forbids the URL for this user agent."""


class SSRFBlocked(MimicError):
    """The URL resolves to a private/loopback/link-local address that was not allowed."""


class CircuitOpenError(MimicError):
    """Too many consecutive failures for this host; calls are short-circuited for a while."""


class AuthFlowError(MimicError):
    """A learned login/refresh chain could not produce a token."""


def _http_error(status: int, url: str, body: bytes, headers: Mapping[str, str]) -> HTTPError:
    if status == 429:
        return RateLimited(status, url, body, headers)
    if 400 <= status < 500:
        return ClientHTTPError(status, url, body, headers)
    if status >= 500:
        return ServerHTTPError(status, url, body, headers)
    return HTTPError(status, url, body, headers)


# ---------------------------------------------------------------- schemas ---
def _jtype(v: Any) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "boolean"
    if isinstance(v, int):
        return "integer"
    if isinstance(v, float):
        return "number"
    if isinstance(v, list):
        return "array"
    if isinstance(v, dict):
        return "object"
    return "string"


def infer_schema(value: Any, _max_items: int = 50, _depth: int = 0) -> JSONSchema:
    """Infer a small JSON-schema subset (type/properties/required/items) from a value."""
    t = _jtype(value)
    s: JSONSchema = {"type": [t]}
    if _depth > 24:
        return s
    if t == "object":
        s["properties"] = {str(k): infer_schema(v, _max_items, _depth + 1) for k, v in value.items()}
        s["required"] = sorted(str(k) for k in value)
    elif t == "array":
        item: JSONSchema | None = None
        for v in value[:_max_items]:
            item = merge_schema(item, infer_schema(v, _max_items, _depth + 1))
        if item is not None:
            s["items"] = item
    return s


def merge_schema(a: JSONSchema | None, b: JSONSchema | None) -> JSONSchema | None:
    """Union of two inferred schemas (fields missing on either side become optional)."""
    if a is None:
        return b
    if b is None:
        return a
    types = sorted(set(a.get("type", [])) | set(b.get("type", [])))
    if "integer" in types and "number" in types:
        types.remove("integer")
    out: JSONSchema = {"type": types}
    if "properties" in a or "properties" in b:
        pa: dict[str, JSONSchema] = a.get("properties", {})
        pb: dict[str, JSONSchema] = b.get("properties", {})
        out["properties"] = {k: merge_schema(pa.get(k), pb.get(k)) for k in sorted(set(pa) | set(pb))}
        ra = set(a.get("required", [])) if "properties" in a else set(pb)
        rb = set(b.get("required", [])) if "properties" in b else set(pa)
        out["required"] = sorted(ra & rb)
    if "items" in a or "items" in b:
        out["items"] = merge_schema(a.get("items"), b.get("items"))
    return out


def diff_schema(old: JSONSchema | None, new: JSONSchema | None, path: str = "$") -> list[dict[str, Any]]:
    """How ``new`` drifted from ``old``: list of {path, kind, detail, breaking}."""
    out: list[dict[str, Any]] = []
    if old is None or new is None:
        return out

    def norm(ts: Sequence[str]) -> set[str]:
        return {"number" if t == "integer" else t for t in ts if t != "null"}

    ot, nt = norm(old.get("type", [])), norm(new.get("type", []))
    if ot and nt:  # null-only observations carry no type information
        if not (ot & nt):
            out.append(
                {
                    "path": path,
                    "kind": "type-changed",
                    "detail": f"{sorted(old['type'])} -> {sorted(new['type'])}",
                    "breaking": True,
                }
            )
            return out
        if not nt <= ot:
            out.append(
                {
                    "path": path,
                    "kind": "type-widened",
                    "detail": f"{sorted(old['type'])} -> {sorted(new['type'])}",
                    "breaking": False,
                }
            )
    if "properties" in old and "properties" in new:
        po: dict[str, JSONSchema] = old["properties"]
        pn: dict[str, JSONSchema] = new["properties"]
        req = set(old.get("required", []))
        for k in sorted(po):
            if k not in pn:
                out.append(
                    {
                        "path": f"{path}.{k}",
                        "kind": "removed",
                        "detail": "field missing from live response",
                        "breaking": k in req,
                    }
                )
            else:
                out.extend(diff_schema(po[k], pn[k], f"{path}.{k}"))
        out.extend(
            {"path": f"{path}.{k}", "kind": "added", "detail": "new field", "breaking": False}
            for k in sorted(set(pn) - set(po))
        )
    if "items" in old and "items" in new:
        out.extend(diff_schema(old["items"], new["items"], f"{path}[]"))
    return out


def get_path(value: Any, dotted: str | Sequence[str] | None) -> Any:
    """Walk a dotted path ("a.b.0.c"); integer parts index lists. Missing => None."""
    if not dotted:
        return value
    parts = list(dotted) if isinstance(dotted, (list, tuple)) else str(dotted).split(".")
    for part in parts:
        if isinstance(value, dict):
            value = value.get(part)
        elif isinstance(value, list) and str(part).lstrip("-").isdigit():
            i = int(part)
            value = value[i] if -len(value) <= i < len(value) else None
        else:
            return None
    return value


def set_path(obj: dict[str, Any], path: str | Sequence[str], value: Any) -> dict[str, Any]:
    """Set a nested field, creating dicts as needed: set_path(b, ["filters", "country"], "FR")."""
    parts = list(path) if isinstance(path, (list, tuple)) else str(path).split(".")
    cur = obj
    for part in parts[:-1]:
        nxt = cur.get(part)
        if not isinstance(nxt, dict):
            nxt = {}
            cur[part] = nxt
        cur = nxt
    cur[parts[-1]] = value
    return obj


