def _link_header_next(headers: Mapping[str, str] | None) -> str | None:
    v = {k.lower(): x for k, x in (headers or {}).items()}.get("link") or ""
    for part in v.split(","):
        seg = part.split(";")
        if len(seg) > 1 and any(p.strip().replace(" ", "") in ('rel="next"', "rel=next") for p in seg[1:]):
            return seg[0].strip().strip("<>")
    return None


def find_next_link(response: Any, headers: Mapping[str, str] | None = None) -> tuple[str | None, str | None]:
    """(dotted_path, url) of a 'next page' URL in a response (or the HTTP Link header)."""
    if isinstance(response, dict):
        for w in _WRAPPERS:
            node = get_path(response, w) if w else response
            if not isinstance(node, dict):
                continue
            for k in _NEXT_KEYS:
                v = node.get(k)
                key = k
                if isinstance(v, dict):
                    key = k + (".href" if v.get("href") else ".url")
                    v = v.get("href") or v.get("url")
                if isinstance(v, str) and (v.startswith(("http://", "https://", "/")) or "?" in v):
                    return (f"{w}.{key}" if w else key), v
    link = _link_header_next(headers)
    return ("<Link>", link) if link else (None, None)


def find_cursor(response: Any) -> tuple[str | None, Any]:
    """(dotted_path, value) of an opaque next-page cursor in a response."""
    if not isinstance(response, dict):
        return None, None
    for w in _WRAPPERS:
        node = get_path(response, w) if w else response
        if not isinstance(node, dict):
            continue
        for k in _CURSOR_KEYS:
            v = node.get(k)
            if (
                isinstance(v, (str, int))
                and not isinstance(v, bool)
                and str(v)
                and not str(v).startswith(("http://", "https://"))
            ):
                return (f"{w}.{k}" if w else k), v
    return None, None


def find_total(response: Any) -> tuple[str | None, int | None]:
    if isinstance(response, dict):
        for w in ("", "meta", "page_metadata", "pagination", "paging", "data", "result"):
            node = get_path(response, w) if w else response
            if isinstance(node, dict):
                for k in _TOTAL_KEYS:
                    v = node.get(k)
                    if isinstance(v, (int, str)) and not isinstance(v, bool) and str(v).isdigit():
                        return (f"{w}.{k}" if w else k), int(v)
    return None, None


# ------------------------------------------------------------- politeness ---
class RateLimiter:
    """Minimum interval between requests, shared by every client instance per host."""

    _locks: ClassVar[dict[str, _threading.Lock]] = {}
    _last: ClassVar[dict[str, float]] = {}
    _guard: ClassVar[_threading.Lock] = _threading.Lock()

    def __init__(self, host: str, min_interval: float = 1.0) -> None:
        self.host, self.min_interval = host, float(min_interval)
        with RateLimiter._guard:
            RateLimiter._locks.setdefault(host, _threading.Lock())

    def reserve(self) -> float:
        """Claim the next slot; returns how long the caller must sleep before sending."""
        with RateLimiter._locks[self.host]:
            now = _time.monotonic()
            slot = max(now, RateLimiter._last.get(self.host, 0.0) + self.min_interval)
            RateLimiter._last[self.host] = slot
            return slot - now

    def wait(self) -> None:
        delay = self.reserve()
        if delay > 0:
            _time.sleep(delay)


class CircuitBreaker:
    """Per-host breaker: ``threshold`` consecutive failures open it for ``reset_after`` seconds,
    then one trial call is let through (half-open); success closes it, failure re-opens it.
    """

    _registry: ClassVar[dict[str, CircuitBreaker]] = {}
    _guard: ClassVar[_threading.Lock] = _threading.Lock()

    def __init__(self, host: str, threshold: int = 10, reset_after: float = 30.0) -> None:
        self.host, self.threshold, self.reset_after = host, max(1, threshold), reset_after
        self.failures, self.opened_at, self.state = 0, 0.0, "closed"
        self._lock = _threading.Lock()

    @classmethod
    def for_host(cls, host: str, threshold: int = 10, reset_after: float = 30.0) -> CircuitBreaker:
        with cls._guard:
            br = cls._registry.get(host)
            if br is None:
                br = cls._registry[host] = cls(host, threshold, reset_after)
            return br

    @classmethod
    def reset_all(cls) -> None:
        with cls._guard:
            cls._registry.clear()

    def before(self) -> None:
        with self._lock:
            if self.state == "open":
                if _time.monotonic() - self.opened_at < self.reset_after:
                    raise CircuitOpenError(
                        f"circuit open for {self.host} after {self.failures} consecutive failures; "
                        f"retry in {self.reset_after - (_time.monotonic() - self.opened_at):.0f}s"
                    )
                self.state = "half-open"
                _event(_logging.INFO, "circuit_half_open", host=self.host)

    def success(self) -> None:
        with self._lock:
            if self.state != "closed":
                _event(_logging.INFO, "circuit_closed", host=self.host)
            self.failures, self.state = 0, "closed"

    def failure(self) -> None:
        with self._lock:
            self.failures += 1
            if self.state == "half-open" or self.failures >= self.threshold:
                if self.state != "open":
                    _event(_logging.WARNING, "circuit_open", host=self.host, failures=self.failures)
                self.state, self.opened_at = "open", _time.monotonic()


# ---------------------------------------------------------------- SSRF ---
_CGNAT = _ipaddress.ip_network("100.64.0.0/10")


def is_private_address(ip: str) -> bool:
    """True for loopback, private, link-local (incl. cloud metadata), CGNAT, multicast, reserved."""
    try:
        addr = _ipaddress.ip_address(ip.split("%")[0])
    except ValueError:
        return True
    if isinstance(addr, _ipaddress.IPv6Address) and addr.ipv4_mapped is not None:
        addr = addr.ipv4_mapped
    return bool(
        addr.is_private
        or addr.is_loopback
        or addr.is_link_local
        or addr.is_multicast
        or addr.is_reserved
        or addr.is_unspecified
        or (isinstance(addr, _ipaddress.IPv4Address) and addr in _CGNAT)
    )


class SSRFGuard:
    """Refuse URLs that resolve to internal addresses unless explicitly allowed.

    ``trusted`` hosts (the ones you configured: BASE_URL/HOSTS/``base_url=``/``allow_hosts=``)
    may be private, e.g. a client learned against ``localhost``. Everything else, including
    URLs that come from *responses* (next-page links, redirects), must resolve to public
    addresses. Resolution results are cached for ``ttl`` seconds.
    """

    def __init__(self, trusted: Sequence[str] = (), allow_private: bool = False, ttl: float = 60.0) -> None:
        self.trusted = {h.lower() for h in trusted if h}
        self.allow_private, self.ttl = allow_private, ttl
        self._cache: dict[str, tuple[float, bool]] = {}

    def check(self, url: str) -> None:
        p = _urlsplit(url)
        if p.scheme not in ("http", "https"):
            raise SSRFBlocked(f"scheme {p.scheme!r} not allowed (http/https only): {url[:80]}")
        host = (p.hostname or "").lower()
        if not host:
            raise SSRFBlocked(f"no host in URL {url[:80]!r}")
        if self.allow_private or host in self.trusted or (p.netloc.lower() in self.trusted):
            return
        hit = self._cache.get(host)
        if hit is None or _time.monotonic() - hit[0] > self.ttl:
            try:
                infos = _socket.getaddrinfo(
                    host, p.port or (443 if p.scheme == "https" else 80), proto=_socket.IPPROTO_TCP
                )
                private = any(is_private_address(str(i[4][0])) for i in infos) or not infos
            except (OSError, UnicodeError):
                private = False  # unresolvable: the request itself will fail with a TransportError
            hit = (_time.monotonic(), private)
            self._cache[host] = hit
        if hit[1]:
            _event(_logging.WARNING, "ssrf_blocked", host=host)
            raise SSRFBlocked(
                f"{host} resolves to a private/internal address; pass allow_hosts=[{host!r}] or "
                f"allow_private=True (or set MIMICPLUS_ALLOW_PRIVATE=1) if this is intended"
            )


# ------------------------------------------------------------- transport ---
@_dataclass
class PreparedRequest:
    method: str
    url: str
    headers: Headers
    body: bytes | None
    timeout: float
    retryable: bool = False
    own_host: bool = True
    meta: dict[str, Any] = _field(default_factory=dict)


@_dataclass
class RawResponse:
    status: int
    headers: Headers
    body: bytes
    url: str = ""
    set_cookies: list[str] = _field(default_factory=list)  # every Set-Cookie (headers dict keeps one)


Transport = Callable[[PreparedRequest], RawResponse]


class _GuardedRedirects(_urequest.HTTPRedirectHandler):
    """Re-run the SSRF guard on every redirect hop and never forward credentials cross-host."""

    def __init__(self, guard: SSRFGuard, strip: Sequence[str]) -> None:
        super().__init__()
        self.guard, self.strip = guard, {s.lower() for s in strip}

    def redirect_request(
        self, req: _urequest.Request, fp: Any, code: int, msg: str, headers: Any, newurl: str
    ) -> _urequest.Request | None:
        self.guard.check(newurl)
        new = super().redirect_request(req, fp, code, msg, headers, newurl)
        if new is not None and _urlsplit(newurl).netloc != _urlsplit(req.full_url).netloc:
            for h in list(new.headers):
                if h.lower() in self.strip or h.lower() in ("authorization", "cookie"):
                    del new.headers[h]
        return new


class UrllibTransport:
    """Default stdlib transport (urllib) with guarded redirects."""

    def __init__(self, guard: SSRFGuard, secret_headers: Sequence[str] = ()) -> None:
        self.opener = _urequest.build_opener(_GuardedRedirects(guard, secret_headers))

    def __call__(self, req: PreparedRequest) -> RawResponse:
        r = _urequest.Request(req.url, data=req.body, headers=req.headers, method=req.method)
        try:
            with self.opener.open(r, timeout=req.timeout) as resp:
                return RawResponse(
                    resp.status,
                    dict(resp.headers),
                    resp.read(),
                    resp.geturl(),
                    resp.headers.get_all("set-cookie") or [],
                )
        except _uerror.HTTPError as e:
            ehs: Any = e.headers  # may be None for synthetic errors
            cookies = ehs.get_all("set-cookie") if ehs is not None else None
            return RawResponse(e.code, dict(e.headers or {}), e.read() or b"", req.url, cookies or [])
        except TimeoutError as e:
            raise RequestTimeout(
                f"{req.method} {req.url.split('?')[0]} timed out after {req.timeout}s"
            ) from e
        except _uerror.URLError as e:
            if isinstance(e.reason, TimeoutError):
                raise RequestTimeout(f"{req.method} {req.url.split('?')[0]} timed out") from e
            if isinstance(e.reason, MimicError):
                raise e.reason from e
            raise TransportError(f"{req.method} {req.url.split('?')[0]} failed: {e.reason}") from e
        except (ConnectionError, OSError) as e:
            raise TransportError(f"{req.method} {req.url.split('?')[0]} failed: {e}") from e


ROBOTS_POLICIES = ("deny", "allow", "warn")


class Robots:
    """robots.txt per RFC 9309: 4xx => allow all.

    5xx / network failure ("unreachable") follows a policy: "deny" (RFC default: assume
    complete disallow), "allow", or "warn" (allow and log a warning). Set it per client
    (robots_unreachable=...) or globally with $MIMICPLUS_ROBOTS_UNREACHABLE.
    """

    _cache: ClassVar[dict[str, _RobotFileParser | None]] = {}
    UNREACHABLE: ClassVar[None] = None

    @classmethod
    def fetch(cls, root: str, user_agent: str, timeout: float = 15) -> _RobotFileParser | None:
        if root in cls._cache:
            return cls._cache[root]
        rp: _RobotFileParser | None = _RobotFileParser()
        try:
            req = _urequest.Request(
                root + "/robots.txt", headers={"User-Agent": user_agent, "Accept-Encoding": "gzip"}
            )
            with _urequest.urlopen(req, timeout=timeout) as r:
                raw = _decompress(r.read(), dict(r.headers))
                assert rp is not None  # noqa: S101 - narrows the Optional for mypy
                rp.parse(raw.decode("utf-8", "replace").splitlines())
        except _uerror.HTTPError as e:
            if 400 <= e.code < 500 and rp is not None:
                rp.parse(["User-agent: *", "Allow: /"])  # RFC 9309: 4xx => no restrictions
            else:
                rp = cls.UNREACHABLE
        except (OSError, ValueError):
            rp = cls.UNREACHABLE
        cls._cache[root] = rp
        return rp

    @classmethod
    def allowed(cls, url: str, user_agent: str, timeout: float = 15, unreachable: str = "deny") -> bool:
        p = _urlsplit(url)
        rp = cls.fetch(f"{p.scheme}://{p.netloc}", user_agent, timeout)
        if rp is None:
            if unreachable == "warn":
                _log.warning(
                    "robots.txt for %s unreachable; proceeding (robots_unreachable='warn')",
                    p.netloc,
                    extra={"fields": {"host": p.netloc}},
                )
            return unreachable in ("allow", "warn")
        return rp.can_fetch(user_agent, url)


# ------------------------------------------------------------ pagination ---
class _Pager:
    """Pagination state machine shared by the sync and async drivers.

    ``plan()`` says what to call next: ``("call", kwargs)`` / ``("get", url)`` / ``("stop", None)``;
    ``feed(resp, items)`` advances the state from a page.
    """

    def __init__(
        self, rc: Mapping[str, Any], kw: Mapping[str, Any], max_pages: int, max_items: int | None
    ) -> None:
        self.rc: dict[str, Any] = dict(rc)
        self.style: str | None = self.rc.get("style")
        self.kw: dict[str, Any] = dict(kw)
        self.max_pages, self.max_items = max_pages, max_items
        self.page_size = self.kw.get(self.rc["size_param"]) if self.rc.get("size_param") else None
        if self.style in ("page", "offset") and self.rc.get("param") not in self.kw:
            self.kw[self.rc["param"]] = int(self.rc.get("start", 1 if self.style == "page" else 0))
        self.pages, self.n_items, self.seen = 0, 0, set[str]()
        self.next_url: str | None = None
        self.done = False

    def plan(self) -> tuple[str, Any]:
        if self.done or self.pages >= self.max_pages:
            return "stop", None
        if self.next_url:
            return "get", self.next_url
        return "call", dict(self.kw)

    def take(self, items: list[Any]) -> list[Any]:
        """Items of this page to yield (respects max_items; detects repeated pages)."""
        self.pages += 1
        sig = _json.dumps(items[:3], sort_keys=True, default=str)
        if not items or sig in self.seen:
            self.done = True
            return []
        self.seen.add(sig)
        if self.max_items is not None:
            items = items[: max(0, self.max_items - self.n_items)]
        self.n_items += len(items)
        if self.max_items is not None and self.n_items >= self.max_items:
            self.done = True
        return items

    def feed(
        self, resp: Any, items: list[Any], last_url: str | None, base_url: str, headers: Mapping[str, str]
    ) -> None:
        if self.done:
            return
        rc, style = self.rc, self.style
        total = get_path(resp, rc["total_path"]) if rc.get("total_path") else find_total(resp)[1]
        reached = total is not None and str(total).isdigit() and self.n_items >= int(total)
        ps = self.page_size
        short = ps is not None and bool(ps) and len(items) < int(ps)
        if style in ("page", "offset"):
            if short or reached:
                self.done = True
            else:
                step = 1 if style == "page" else len(items)
                self.kw[rc["param"]] = int(self.kw[rc["param"]]) + step
            return
        if style == "cursor":
            cur = get_path(resp, rc["cursor_path"]) if rc.get("cursor_path") else find_cursor(resp)[1]
            if cur in (None, "", False):
                self.done = True
            else:
                self.kw[rc["param"]] = cur
            return
        nxt: Any = None
        if rc.get("next_path") and rc["next_path"] != "<Link>":
            nxt = get_path(resp, rc["next_path"])
            if isinstance(nxt, dict):
                nxt = nxt.get("href") or nxt.get("url")
        if not nxt:
            nxt = find_next_link(resp, headers)[1]
        if not nxt:
            if style is None:  # auto mode: fall back to a response cursor
                cpath, cur = find_cursor(resp)
                cparam = rc.get("param") or (cpath.split(".")[-1] if cpath else None)
                if cur not in (None, "") and cparam:
                    self.style, self.rc["param"] = "cursor", cparam
                    self.kw[cparam] = cur
                    return
            self.done = True
            return
        nxt = str(nxt)
        if nxt.startswith("/"):
            p = _urlsplit(last_url or base_url)
            nxt = f"{p.scheme}://{p.netloc}{nxt}"
        elif nxt.startswith("?"):
            nxt = (last_url or base_url).split("?")[0] + nxt
        self.style = style or "next"
        self.next_url = nxt


